<script lang="ts">
 import Spooly from './Spooly.svelte';
 import CompanyAddressFields from './CompanyAddressFields.svelte';
 import BusinessFlowSelect from './BusinessFlowSelect.svelte';
 import {businessFlows, businessFlowMatches} from './businessFlows';
 import {companyFieldApplies,companyFieldRequest} from './companyFields';
 import SidebarToggle from "./SidebarToggle.svelte";
 import {workspaceRedirect} from './workspaceAccess';
 import SignInForm from "./SignInForm.svelte";
 import {enter, workspaceMotion} from "./motion";
 import "../interactions.css";
 import "../dashboard.css";
 import {onMount,tick} from 'svelte';
 import {goto} from '$app/navigation';
 import CustomCompanyFields from './CustomCompanyFields.svelte';
 import SetupUsers from './SetupUsers.svelte';
 import CompanyAttachments from './CompanyAttachments.svelte';
 import CompanyExpiry from './CompanyExpiry.svelte';
 import CompanyFileActions from './CompanyFileActions.svelte';
 import {unlinkedCompanyFiles,companyHistoryTime,companyFileStorageNote} from './companyDocuments';
 let {portal='',area='companies'}:{portal?:string;area?:string}=$props();
 const portalNames:Record<string,string>={finance:'Finance',md:'MD',admin:'Admin'};
 const areas:Record<string,string>={Companies:'companies',Reminders:'reminders',Registers:'fields',Users:'users',Operations:'operations'};
 let page=$derived(({companies:'Companies',reminders:'Reminders',fields:'Registers',users:'Users'} as Record<string,string>)[area]||'Companies');
 const can=(feature:string)=>!!user?.setup_grants?.includes(feature);
 async function navigate(name:string){if(back())await goto('/'+user?.portal+'/'+areas[name]);}
 import {Building2,ShieldCheck,FileText,Landmark,Plane,Clock,Plus,ArrowLeft,ArrowRight,Check,LogOut,Download,Upload,Search,Settings,Mail,LockKeyhole,RefreshCw,X,ClipboardCheck} from '@lucide/svelte';
 import {api,uploadTo,day} from '$lib/api';
 import type {Row} from '$lib/types';
 import '../app.css';import '../company.css';
 let user:Row|null=$state(null),data:Row=$state({companies:[],fields:[],ports:[],reminders:[],types:{}}),selected:Row|null=$state(null),profile:Row=$state({});
 let ready=$state(false),busy=$state(false),error=$state(''),notice=$state(''),username=$state(''),password=$state(''),section=$state('Overview'),search=$state(''),status=$state('All'),local=$state(false),dirty=$state(false);
 let modal=$state(''),form:Row=$state({}),reviewNote=$state(''),fileInput=$state<HTMLInputElement>(null!);let uploaded=$state(false);
 function renewalState(expiry:string){const today=new Date().toISOString().slice(0,10);const days=Math.round((Date.parse(expiry+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000);return {label:days<0?'Expired '+(-days)+' days ago':days===0?'Expires today':'Due in '+days+' days',overdue:days<0}}
 const businessModes=['Not specified','Domestic','Import','Export','Import & export'];const categories=['Internal','Buyer','Supplier'];const buyerDepts=['Menswear','Womenswear','Kids'];
 const sections=['Overview','Contacts','KYC','Bank accounts','Ports','Trade registrations','Property','Insurance','Additional','Documents','Review'];
 let editable=$derived.by(()=>!!selected?.can_edit&&can('edit'));let privateView=$derived.by(()=>!!selected?.can_view_private);
 let visible=$derived((data.companies||[]).filter((c:Row)=>(status==='All'||c.status===status)&&(!search||(c.legal_name+' '+c.country+' '+c.company_type).toLowerCase().includes(search.toLowerCase()))));
 function fieldApplies(f:Row){return companyFieldApplies(f,selected,(f.country==='*'||f.country===selected?.country)&&f.categories.includes(selected?.category)&&businessFlowMatches(f.business_modes,selected));}
 let definitions:Row[]=$derived((data.fields||[]).filter(fieldApplies));
 let canAddCompanyField=$derived.by(()=>editable&&can('view')&&user?.role==='Finance Head');
 let recoveryFiles:Row[]=$derived.by(()=>unlinkedCompanyFiles(profile,selected?.files||[]));
 let sectionHeading:HTMLHeadingElement|undefined=$state();
 async function selectSection(next:string){section=next;await tick();const heading=sectionHeading;if(!heading)return;heading.focus({preventScroll:true});let parent=heading.parentElement;while(parent&&parent!==document.body&&parent!==document.documentElement){if(parent.scrollHeight>parent.clientHeight&&/(auto|scroll)/.test(getComputedStyle(parent).overflowY))parent.scrollTop=0;parent=parent.parentElement;}const topbar=document.querySelector('.company-topbar');window.scrollTo({top:Math.max(0,window.scrollY+heading.getBoundingClientRect().top-(topbar?.getBoundingClientRect().height||0)-20),behavior:'instant'});}
 let outstanding=$derived((data.companies||[]).filter((c:Row)=>c.status==='Pending').length);
 const isFinance=()=>user?.role==='Finance Head';const isApprover=()=>can('approve');const isSuper=()=>user?.role==='Super Admin';
 async function load(){if(!can('view')){data={companies:[],fields:[],ports:[],reminders:[],types:{}};return;}data=await api('/company-setup');user=data.user;local=data.local;}
 onMount(()=>{const requested=new URL(location.href).searchParams.get('account');if(requested)username=requested;let active=true;(async()=>{try{const s=await api('/session');local=s.local;if(s.user&&requested&&s.user.username!==requested){await api('/logout',{});}else if(s.user){user=s.user;const redirect=workspaceRedirect(s.user,portal,'companies');if(redirect){window.location.replace(redirect+location.search);return;}await load();}}catch(e){error=(e as Error).message;}finally{if(active)ready=true;}})();const expired=()=>{user=null;selected=null;error='Please sign in again.';};window.addEventListener('erp:session-expired',expired);return()=>{active=false;window.removeEventListener('erp:session-expired',expired)}});
 async function run(fn:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await fn();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function signedIn(result:Row){user=result.user;const redirect=workspaceRedirect(result.user,portal,'companies');if(redirect){window.location.replace(redirect+location.search);return;}await load();}
 async function logout(){await run(async()=>{await api('/logout',{});user=null;selected=null;dirty=false;})}
 function cleanProfile(p:Row={}){return {address:'',state:'',postal_code:'',email:'',phone:'',website:'',owner:'',sample_address:'',brands:'',departments:[],ownership:'',relationship:'',nominated_by:'',supplier_services:'',reminder_email:'',supplier_group:'',notes:'',...p,reminder_emails:p.reminder_emails||[],contacts:p.contacts||[],banks:p.banks||[],ports:p.ports||[],trade_registrations:p.trade_registrations||[],fields:p.fields||[]};}
 function ensureFields(){if(!selected?.can_view_private)return;const defs=data.fields.filter(fieldApplies);profile.fields=profile.fields.filter((v:Row)=>defs.some((d:Row)=>d.id===v.id));for(const d of defs){if(!profile.fields.some((v:Row)=>v.id===d.id))profile.fields.push({id:d.id,value:'',not_applicable:false,reason:'',expiry:d.expiry_enabled,reminder_enabled:false,reminder_emails:[],valid_from:'',expires_on:'',documents:[]});}}
 async function open(id:number){await run(async()=>{selected=await api('/company-setup/'+id);profile=cleanProfile(selected?.profile);section='Overview';dirty=false;ensureFields();})}
 async function reloadSelected(){if(!selected)return;selected=await api('/company-setup/'+selected.id);profile=cleanProfile(selected?.profile);ensureFields();dirty=false;}
 async function save(){if(!selected)return;await api('/company-setup/'+selected.id,{action:'save',version:selected.version,legal_name:selected.legal_name,category:selected.category,company_type:selected.company_type,country:selected.country,city:selected.city,business_flows:businessFlows(selected),profile});await reloadSelected();await load();notice='Draft saved.';}
 async function action(action:string){await run(async()=>{if(!selected)return;if(action==='submit'&&dirty)await save();await api('/company-setup/'+selected.id,{action,version:selected.version,note:reviewNote});await reloadSelected();await load();modal='';notice=action==='submit'?'Submitted. MD or Super Admin can now review the company.':action==='approve'?'Company approved.':action==='amend'?'Amendment opened. Save and submit for fresh approval.':'Changes requested.';})}
 let deleteName=$state(''),deletePassword=$state('');let responsibleUsers:Row[]=$state([]),responsibleID=$state<number>(0);
 async function deleteCompany(e:SubmitEvent){e.preventDefault();if(!selected||deleteName!==selected.legal_name)return;await run(async()=>{await api('/company-setup/'+selected!.id+'/delete',{confirmation_name:deleteName,password:deletePassword,version:selected!.version});selected=null;profile=cleanProfile();dirty=false;modal='';deleteName='';deletePassword='';await load();notice='Company deleted from the register.';})}
 function back(){if(dirty&&!window.confirm('Leave this draft without saving your changes?'))return false;selected=null;dirty=false;error='';return true;}
 function modalDialog(node:HTMLDialogElement){node.showModal();const motion=enter(node);return {destroy(){motion.destroy();node.close()}}}
 function showModal(kind:string){if(kind==='company_field'&&!canAddCompanyField)return;error='';modal=kind;form=kind==='company'?{legal_name:'',category:'Internal',company_type:'Self',country:'IN',city:'',address:'',state:'',postal_code:'',business_flows:[]}:kind==='type'?{category:'Supplier',label:''}:kind==='field'||kind==='company_field'?{label:'',section:kind==='company_field'?'Additional':'KYC',country:'*',categories:['Internal','Buyer','Supplier'],input_type:'text',required:false,document_required:false,expiry_enabled:false,options_text:'',business_modes:[]}:{name:'',code:'',country:selected?.country||'IN',mode:'Sea'};}
 async function submitModal(e:SubmitEvent){e.preventDefault();await run(async()=>{const kind=modal;if(kind==='company_field'){if(!selected||!canAddCompanyField)throw new Error('This company is no longer available for editing.');const result=await api('/company-setup/'+selected.id+'/fields',companyFieldRequest(form,selected.version));selected.version=result.version;data.fields=[...(data.fields||[]),result.field];ensureFields();dirty=true;modal='';notice='Field added. Complete it below and save your draft.';return;}if(kind==='field')form.options=form.input_type==='select'?(form.options_text||'').split('\n').map((v:string)=>v.trim()).filter(Boolean):[];const result=await api(kind==='company'?'/company-setup':kind==='field'?'/company-fields':kind==='type'?'/company-types':'/company-ports',form);await load();modal='';if(kind==='company'){selected=await api('/company-setup/'+result.id);profile=cleanProfile(selected?.profile);section='Overview';ensureFields();dirty=false;}else{if(kind==='field')ensureFields();notice=kind==='field'?'Custom field added.':kind==='type'?'Company type added.':'Port added to the registry.';}})}
 function field(id:number):Row{return profile.fields.find((f:Row)=>f.id===id)}
 function addContact(){profile.contacts.push({role:'Owner',name:'',email:'',phone:''});dirty=true}
 function addBank(){profile.banks.push({id:crypto.randomUUID(),name:'',holder:'',account:'',account_type:'',routing:'',currency:'INR',documents:[]});dirty=true}
 function addPort(){profile.ports.push({id:'',default:false,registered:false,registration:'',bank_id:'',expiry:false,reminder_enabled:false,reminder_emails:[],valid_from:'',expires_on:'',documents:[]});dirty=true}
 function toggleDoc(target:Row,id:number,checked:boolean){target.documents=checked?[...new Set([...(target.documents||[]),id])]:(target.documents||[]).filter((v:number)=>v!==id);dirty=true}
 function notApplicable(f:Row){if(f.not_applicable){f.value='';f.documents=[];f.expiry=false;f.reminder_enabled=false;f.reminder_emails=[];f.valid_from='';f.expires_on=''}dirty=true}
 async function uploadAt(target:Row|null,file:File){if(!selected)return;await run(async()=>{const result=await uploadTo('/company-setup/'+selected!.id+'/files',file);const current=await api('/company-setup/'+selected!.id);selected!.files=current.files;selected!.history=current.history;if(target){target.documents=[...new Set([...(target.documents||[]),result.id])];dirty=true;}const storageNote=companyFileStorageNote(result);notice=(target?'Document uploaded and linked. Save your draft to keep this link.':'Document uploaded.')+(storageNote?' '+storageNote+'.':'');})}
 async function uploadFile(){const file=fileInput.files?.[0];if(file){await uploadAt(null,file);fileInput.value=''}}
 async function openResponsibility(){await run(async()=>{const result=await api('/setup-users');responsibleUsers=result.users.filter((u:Row)=>u.active&&u.role!=='Super Admin');responsibleID=selected?.responsible_user_id||0;modal='responsibility'})}
 async function saveResponsibility(e:SubmitEvent){e.preventDefault();await run(async()=>{await api('/company-setup/'+selected!.id+'/responsibility',{user_id:responsibleID,version:selected!.version});modal='';await reloadSelected();notice='Renewal responsibility updated.'})}

</script>

<svelte:head><title>Euro Suits · Company Setup</title></svelte:head>
{#if !ready}<main class="loading-screen"><img src="/logo.png" alt="Euro Suits"/><p>Opening Company Setup…</p></main>
{:else if !user}
<main class="login-layout"><section class="login-brand"><div class="login-brand-name"><img src="/logo.png" alt="Euro Suits logo"/><span>EURO SUITS</span></div><div><p class="eyebrow">EURO SUITS WORKSPACE</p><h1>A clear start.<br/>A trusted<br/><span>company record.</span></h1><p>Company details, KYC and approvals in one place.</p></div><small>EURO SUITS OPERATIONS</small></section><section class="login-panel"><div class="login-form-wrap" use:enter><span class="login-symbol"><LockKeyhole size={24}/></span><h1>{portal?portalNames[portal]+' sign in':'Welcome back'}</h1><p class="muted">{portal?'Use your individual '+portalNames[portal]+' account.':'Sign in to your workspace.'}</p><SignInForm {portal} initialUsername={username} onauthenticated={signedIn}/>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<div class="role-shortcuts"><span>Role login pages</span>{#each [['finance','Finance Head'],['md','MD'],['admin','Super Admin']] as account}<button onclick={()=>goto('/'+(account[0]==='admin'?'admin':account[0]))}>{account[1]}</button>{/each}</div>{#if local}<p class="login-help">Local test credentials are in the private LOCAL-ACCESS.txt file.</p>{/if}</div></section></main>
{:else}
<div class="company-app erp-workspace"><a class="workspace-skip" href="#workspace-content">Skip to workspace</a><aside class="company-sidebar"><div class="brand"><img src="/logo.png" alt="Euro Suits logo"/><div><strong>EURO SUITS</strong><span>OPERATIONS</span></div></div><div class="phase-pill">WORKSPACE <span>Company Setup</span></div><nav aria-label="Company navigation">{#if user.grants?.includes('export_view')}<button onclick={()=>{if(back())goto('/exports')}}><Plane size={19}/>Export Documentation</button>{/if}{#if user.grants?.includes('view_orders')}<button onclick={()=>navigate('Operations')}><Building2 size={19}/>Operations</button>{/if}<button class:active={page==='Companies'} onclick={()=>{navigate('Companies')}}><Building2 size={19}/>Companies</button>{#if can('reminders')}<button class:active={page==='Reminders'} onclick={()=>{navigate('Reminders')}}><Clock size={19}/>Renewal reminders{#if data.reminders.length}<b>{data.reminders.length}</b>{/if}</button>{/if}<button class:active={page==='Registers'} onclick={()=>{navigate('Registers')}}><Settings size={19}/>Fields & ports</button>{#if isSuper()}<button class:active={page==='Users'} onclick={()=>navigate('Users')}><ShieldCheck size={19}/>User access</button>{/if}</nav><div class="company-sidebar-note"><ShieldCheck size={20}/><strong>Controlled company setup</strong><p>Finance prepares. MD or Super Admin approves.</p></div><footer><strong>{user.name}</strong><small>{user.role}</small><button onclick={logout} disabled={busy}><LogOut size={16}/>Sign out</button></footer></aside>
<div class="company-main"><header class="company-topbar"><span><SidebarToggle/>Workspace <span class="muted">/</span> <strong>Company Setup</strong></span><div>{#if local}<span class="local-chip">Local workspace</span>{/if}<span class="role-pill">{user.role}</span><button class="icon-button" aria-label="Refresh company register" disabled={busy||dirty} onclick={()=>run(load)}><RefreshCw size={17}/></button></div></header><main id="workspace-content" class="company-content" tabindex="-1" use:workspaceMotion={page+':'+(selected?.id||'')}>
{#if error}<div class="form-error" role="alert">{error}</div>{/if}{#if notice}<div class="company-notice" role="status" use:enter={notice}><Check size={17}/>{notice}</div>{/if}
{#if user.renewal_blocks?.length&&!selected}<section class="panel company-section"><h1>Renewal action required</h1><p class="company-warning">Your normal dashboard is locked because a renewal is at least 30 days overdue. Update the document and obtain approval to restore access.</p>{#each user.renewal_blocks as block}<div class="detail-card"><strong>{block.legal_name}</strong><p>{block.label} · Expired {day(block.expires_on)}</p>{#if can('view')}<button class="button primary" onclick={()=>open(block.id)}>Open renewal record</button>{/if}</div>{/each}<p>Contact Finance to prepare the renewal and MD or Super Admin to approve it.</p></section>
{:else if !can('view')}<section class="panel company-empty"><h1>No features assigned</h1><p>Ask Admin to enable access for your account.</p></section>
{:else if page==='Users'}{#if isSuper()}<SetupUsers currentUser={user}/>{:else}<p class="company-warning">Only Admin can manage user access.</p>{/if}
{:else if page==='Reminders'&&!can('reminders')}<p class="company-warning">Reminders are not enabled for your account.</p>
{:else if selected}
<div class="company-detail-heading" use:enter={selected?.id}><button class="text-button" onclick={back}><ArrowLeft size={16}/>Company register</button><div><div><p class="eyebrow">{selected.category} COMPANY · REVISION {selected.revision}</p><h1>{selected.legal_name}</h1><p>{selected.company_type} · {selected.country} {selected.city?'· '+selected.city:''}</p></div><span class={'status-chip '+selected.status.toLowerCase().replaceAll(' ','-')}>{selected.status}</span></div></div>
{#if selected.approval_note&&selected.status==='Changes requested'}<div class="company-warning"><strong>Changes requested</strong><p>{selected.approval_note}</p></div>{/if}
{#if !privateView}
<div class="privacy-banner"><ShieldCheck size={22}/><div><strong>Approval summary</strong><p>Full KYC values, bank details and attachments are restricted to Super Admin after submission.</p></div></div>
<div class="company-summary-grid">{#each [['Contacts','contacts'],['Bank accounts','bank_accounts'],['Ports','ports'],['Documents','documents']] as metric}<div class="panel"><span>{metric[0]}</span><strong>{selected.summary[metric[1]]}</strong></div>{/each}</div>
<section class="panel company-section"><h2>Readiness check</h2>{#if selected.summary.ready}<p class="ready-message"><Check size={18}/>Required details and supporting documents are complete.</p>{:else}<ul class="validation-list">{#each selected.summary.issues as issue}<li>{issue}</li>{/each}</ul>{/if}<p class="muted">Review the field checklist below before approval. Super Admin can inspect the original KYC documents.</p><div class="table-wrap"><table><thead><tr><th>KYC / requirement</th><th>Declaration</th><th>Copies</th><th>Expiry</th></tr></thead><tbody>{#each selected.summary.checklist as item}<tr><td>{item.label}</td><td>{item.state}</td><td>{item.documents}</td><td>{item.expires_on||'—'}</td></tr>{/each}</tbody></table></div></section>
{:else}
<div class="company-editor"><nav class="section-nav" aria-label="Company form sections">{#each sections as s}<button class:active={section===s} onclick={()=>selectSection(s)}>{s}{#if s==='Documents'}<span>{selected.files?.length||0}</span>{/if}</button>{/each}</nav><section class="panel company-section" oninput={()=>dirty=editable||dirty} onchange={()=>dirty=editable||dirty}>
<div class="section-intro">{#if section==='Additional'}<div class="detail-card-heading"><h2 bind:this={sectionHeading} tabindex="-1">{section}</h2>{#if canAddCompanyField}<button type="button" class="button primary" disabled={busy} onclick={()=>showModal('company_field')}><Plus size={16}/>Add field</button>{/if}</div>{:else}<h2 bind:this={sectionHeading} tabindex="-1">{section}</h2>{/if}<p>{section==='Overview'?'Start with the legal identity and registered address.':section==='Documents'?'Every uploaded company document is listed here. Linked copies also stay in their own fields or registrations.':section==='Review'?'Check the record before submitting for approval.':section==='Additional'?'Extra company details and supporting documents.':'Complete the applicable details. For each KYC field, enter the value or mark Not applicable with a reason.'}</p></div>
{#if !editable}<div class="read-only-note"><LockKeyhole size={15}/>Read-only KYC access · {user.role}</div>{/if}
{#if section==='Overview'}
<fieldset disabled={!editable||busy} class="company-form-grid"><label class="wide">Legal company name<input bind:value={selected.legal_name} maxlength="150" required/></label><label>Company category<select bind:value={selected.category} onchange={()=>{selected!.company_type=data.types[selected!.category][0];ensureFields()}}>{#each categories as c}<option>{c}</option>{/each}</select></label><label>Company type<select bind:value={selected.company_type}>{#each data.types[selected.category] as t}<option>{t}</option>{/each}</select></label><label>Country code<input bind:value={selected.country} maxlength="2" oninput={()=>{selected!.country=selected!.country.toUpperCase()}} onchange={ensureFields}/><small>Two-letter code, e.g. IN, GB, US. Fields adapt to this country.</small></label><BusinessFlowSelect values={businessFlows(selected)} disabled={!editable||busy} onchange={next=>{if(selected){selected.business_flows=next;dirty=true;ensureFields()}}}/><label>Company short code<input bind:value={profile.short_code} maxlength="30"/></label><CompanyAddressFields country={selected.country} city={selected.city} state={profile.state} postalCode={profile.postal_code} address={profile.address} disabled={!editable||busy} onchange={patch=>{if(!selected||!editable||busy)return;if(patch.city!==undefined)selected.city=patch.city;if(patch.state!==undefined)profile.state=patch.state;if(patch.postalCode!==undefined)profile.postal_code=patch.postalCode;if(patch.address!==undefined)profile.address=patch.address;dirty=true;}}/><label>Owner / legal representative{selected.category==='Internal'?'':' (if known)'}<input bind:value={profile.owner}/></label><label>Company contact number<input bind:value={profile.phone} type="tel"/></label><label>Company email<input bind:value={profile.email} type="email"/></label><label>Website<input bind:value={profile.website} type="url" placeholder="https://"/></label>
{#if selected.category==='Buyer'}<label class="wide">Sample delivery address<textarea rows="3" bind:value={profile.sample_address}></textarea></label><label class="wide">Brands<input bind:value={profile.brands}/></label><fieldset class="wide inline-checks"><legend>Departments</legend>{#each buyerDepts as d}<label><input type="checkbox" value={d} bind:group={profile.departments}/>{d}</label>{/each}</fieldset>{/if}
{#if selected.category==='Supplier'}<label>Supplier code<input bind:value={profile.supplier_code} maxlength="50"/></label><label>Dial code<input bind:value={profile.dial_code} maxlength="20"/></label><label>Fax number<input bind:value={profile.fax} maxlength="80"/></label><label>Supplier group<select bind:value={profile.supplier_group}><option value="">Select group</option>{#each ['Raw materials','Finished goods','Consumables','Machinery','Services','Logistics'] as group}<option>{group}</option>{/each}</select></label><label>Supplier relationship<select bind:value={profile.relationship}><option value="">Select relationship</option>{#each ['Nominated','Direct','Non-nominated'] as v}<option>{v}</option>{/each}</select></label>{#if profile.relationship==='Nominated'}<label>Nominating buyer reference<input bind:value={profile.nominated_by}/></label>{/if}<label class="wide">Products / services supplied<textarea bind:value={profile.supplier_services} rows="3"></textarea></label>{/if}<label class="wide">Internal notes<textarea bind:value={profile.notes} rows="3"></textarea></label></fieldset>
{:else if section==='Contacts'}
{#each profile.contacts as contact,i}<fieldset disabled={!editable||busy} class="detail-card"><div class="detail-card-heading"><h3>Contact {i+1}</h3>{#if editable}<button class="text-button danger" onclick={()=>{profile.contacts.splice(i,1);dirty=true}}>Remove</button>{/if}</div><div class="company-form-grid"><label>Designation<input bind:value={contact.role} maxlength="100" placeholder="Owner, MD, Sales Head, Marketing Manager…"/></label><label>Full name<input bind:value={contact.name}/></label><label>Email<input bind:value={contact.email} type="email"/></label><label>Phone / mobile<input bind:value={contact.phone} type="tel"/></label><label>Website<input bind:value={contact.website} type="url" placeholder="https://"/></label><label>Skype ID<input bind:value={contact.skype} maxlength="120"/></label><label>Speciality<input bind:value={contact.speciality} maxlength="500"/></label></div></fieldset>{:else}<div class="section-empty"><p>No contact people added yet.</p></div>{/each}{#if editable}<button class="button secondary" onclick={addContact}><Plus size={16}/>Add contact</button>{/if}
{:else if ['KYC','Property','Insurance'].includes(section)}
{#if section==='Property'}<fieldset disabled={!editable} class="company-form-grid"><label>Property ownership<select bind:value={profile.ownership}><option value="">Select ownership</option>{#each ['Owned','Leased','Rented','Not applicable'] as v}<option>{v}</option>{/each}</select></label></fieldset>{/if}
{:else if section==='Bank accounts'}
{#each profile.banks as bank,i}<fieldset disabled={!editable||busy} class="detail-card"><div class="detail-card-heading"><h3>Bank account {i+1}</h3>{#if editable}<button class="text-button danger" onclick={()=>{profile.banks.splice(i,1);dirty=true}}>Remove</button>{/if}</div><div class="company-form-grid"><label>Bank name<input bind:value={bank.name}/></label><label>Bank account type<select bind:value={bank.account_type}><option value="">Choose an account type</option><option>Current</option><option>Savings</option><option value="Cash credit">Cash Credit</option><option>Overdraft</option><option>Other</option></select></label><label>Account holder<input bind:value={bank.holder}/></label><label>Account number / IBAN<input bind:value={bank.account}/></label><label>IFSC / SWIFT / routing code<input bind:value={bank.routing}/></label><label>Currency<input bind:value={bank.currency} maxlength="3"/></label></div><CompanyAttachments target={bank} files={selected.files||[]} {recoveryFiles} {editable} {busy} label="Bank proof" onselect={(id,checked)=>toggleDoc(bank,id,checked)} onupload={can('documents')?(file)=>uploadAt(bank,file):undefined}/></fieldset>{:else}<div class="section-empty"><p>No bank accounts added yet.</p></div>{/each}{#if editable}<button class="button secondary" onclick={addBank}><Plus size={16}/>Add bank account</button>{/if}
{:else if section==='Ports'}
<p class="muted">Use the nearest sea port / inland container depot and airport. Select one default of each for an internal company.</p>
{#each profile.ports as port,i}<fieldset disabled={!editable||busy} class="detail-card"><div class="detail-card-heading"><h3>Port {i+1}</h3>{#if editable}<button class="text-button danger" onclick={()=>{profile.ports.splice(i,1);dirty=true}}>Remove</button>{/if}</div><label>Registered port / airport<select bind:value={port.id}><option value="">Choose a port</option>{#each data.ports as p}<option value={p.id}>{p.name} · {p.mode} · {p.country}</option>{/each}</select></label><div class="inline-checks"><label><input type="checkbox" bind:checked={port.default}/>Default for this transport mode</label><label><input type="checkbox" bind:checked={port.registered} onchange={()=>{if(!port.registered){port.reminder_enabled=false;port.reminder_emails=[]}dirty=true}}/>Company has a port registration</label></div>{#if port.registered}<div class="company-form-grid"><label>Registration number<input bind:value={port.registration}/></label><label>Linked bank account<select bind:value={port.bank_id}><option value="">Choose an account</option>{#each profile.banks as b}<option value={b.id}>{b.name} · {b.account.slice(-4)}</option>{/each}</select></label></div><CompanyExpiry target={port} legacyEmails={selected.legacy_reminder_emails||[]} {editable} {busy} label="this port registration" onpatch={patch=>{Object.assign(port,patch);dirty=true}}/><CompanyAttachments target={port} files={selected.files||[]} {recoveryFiles} {editable} {busy} label="Port registration copies" onselect={(id,checked)=>toggleDoc(port,id,checked)} onupload={can('documents')?(file)=>uploadAt(port,file):undefined}/>{/if}</fieldset>{:else}<div class="section-empty"><p>No ports linked yet.</p></div>{/each}{#if editable}<div class="row-actions"><button class="button secondary" onclick={addPort}><Plus size={16}/>Link a port</button>{#if can('ports')}<button class="text-button" onclick={()=>showModal('port')}>Register a new port</button>{/if}</div>{/if}
{:else if section==='Trade registrations'}
<p class="muted">Record DGFT / ICEGATE registration and advance licence details, linked banks and ports. Entries and proofs are maintained by your team.</p>
{#each profile.trade_registrations as t,i}<fieldset disabled={!editable||busy} class="detail-card"><div class="detail-card-heading"><h3>Registration {i+1}</h3>{#if editable}<button type="button" class="text-button danger" onclick={()=>{profile.trade_registrations.splice(i,1);dirty=true}}>Remove</button>{/if}</div><div class="company-form-grid"><label>Portal<select bind:value={t.portal}><option>DGFT</option><option>ICEGATE</option><option>Other</option></select></label><label>Registration reference<input bind:value={t.registration} maxlength="200"/></label><label>Advance licence / authorisation<input bind:value={t.licence} maxlength="200"/></label><label>Linked bank account<select bind:value={t.bank_id}><option value="">None</option>{#each profile.banks as bank}<option value={bank.id}>{bank.name} · {bank.account.slice(-4)}</option>{/each}</select></label></div><h4>Registered ports</h4><div class="inline-checks">{#each data.ports as port}<label class="inline-check"><input type="checkbox" value={port.id} bind:group={t.port_ids}/>{port.name}</label>{/each}</div><CompanyExpiry target={t} legacyEmails={selected.legacy_reminder_emails||[]} {editable} {busy} label="this trade registration" onpatch={patch=>{Object.assign(t,patch);dirty=true}}/><CompanyAttachments target={t} files={selected.files||[]} {recoveryFiles} {editable} {busy} label="Trade registration proof" onselect={(id,checked)=>toggleDoc(t,id,checked)} onupload={can('documents')?(file)=>uploadAt(t,file):undefined}/></fieldset>{/each}
{#if editable}<button class="button secondary" onclick={()=>{profile.trade_registrations.push({id:crypto.randomUUID(),portal:'DGFT',registration:'',licence:'',bank_id:'',port_ids:[],expiry:false,reminder_enabled:false,reminder_emails:[],valid_from:'',expires_on:'',documents:[]});dirty=true}}>Add trade registration</button>{/if}
{:else if section==='Additional'&&!definitions.some(d=>d.section==='Additional')}
<div class="section-empty"><h3>No additional fields configured</h3><p>{canAddCompanyField?'Add a field for details needed only on this company. You can include supporting documents and expiry dates.':'No additional fields are available for this company.'} Use Documents for other supporting files.</p>{#if can('documents')}<button type="button" class="button secondary" disabled={busy} onclick={()=>selectSection('Documents')}><Plus size={16}/>{editable?'Add document':'View documents'}</button>{/if}</div>
{:else if section==='Documents'}
{#if editable&&can('documents')}<div class="upload-zone"><Upload size={28}/><h3>Upload supporting documents</h3><p>Add extra company records here, or attach a copy directly in its field.</p><label class="button secondary">Upload document<input class="upload-file-input" type="file" bind:this={fileInput} aria-label="Upload company document" accept=".pdf,.png,.jpg,.jpeg,.docx,.xlsx" onchange={uploadFile} disabled={busy}/></label><small>PDF, images, Word or Excel · up to 20 MB each</small><small>New files are compressed automatically when it saves space, without quality loss. Downloads restore the exact original.</small></div>{/if}
<div class="company-document-register">{#each can('documents')?selected.files||[]:[] as doc}<div class="company-file-row"><FileText size={20}/><div class="company-file-name"><strong>{doc.name}</strong><small>{Math.ceil(doc.size/1024)} KB · {recoveryFiles.some(file=>file.id===doc.id)?'unattached supporting document':'linked to a company field or registration'}</small>{#if companyFileStorageNote(doc)}<small>{companyFileStorageNote(doc)}</small>{/if}</div><div class="company-file-actions"><CompanyFileActions {doc}/></div></div>{:else}<p class="section-empty">No documents uploaded yet.</p>{/each}</div>
<p class="muted">Removing a file from a field keeps its original here. Use the field's <strong>Use an unattached document</strong> option to link it again.</p>
{:else if section==='Review'}
<div class="privacy-banner"><ShieldCheck size={20}/><p>Submission locks this record. MD receives a summary; Super Admin can inspect full KYC. Finance gets access again if changes are requested.</p></div>{#if dirty}<p class="company-warning">Save your draft to refresh the readiness check.</p>{/if}{#if selected.summary.ready}<p class="ready-message"><Check size={18}/>This company is ready to submit.</p>{:else}<ul class="validation-list">{#each selected.summary.issues as issue}<li>{issue}</li>{/each}</ul>{/if}
{/if}
{#if section!=='Review'}<CustomCompanyFields legacyEmails={selected.legacy_reminder_emails||[]} definitions={definitions.filter(d=>d.section===section)} bind:profile files={selected.files||[]} {recoveryFiles} {editable} {busy} onchange={()=>dirty=true} onupload={can('documents')?(target,file)=>uploadAt(target,file):undefined}/>{/if}
</section></div>
{/if}
<section class="panel company-history"><h2>Record history</h2>{#each selected.history as h}<div><span class="history-dot"></span><strong>{h.action}</strong><span>{h.actor_role} · Revision {h.revision}</span><small>{companyHistoryTime(h.created_at)}</small></div>{/each}</section>
<div class="company-actionbar"><span>{dirty?'Unsaved changes':selected.status==='Pending'?'Awaiting approval':'Revision '+selected.revision}</span><div>{#if isSuper()}<button class="button secondary" disabled={busy} onclick={openResponsibility}>Renewal responsibility</button><button class="button secondary danger" disabled={busy} onclick={()=>{deleteName='';deletePassword='';error='';modal='delete'}}>Delete company</button>{/if}{#if can('export')}<a class="button secondary" href={'/api/company-setup/'+selected.id+'/export'}><Download size={16}/>Export Excel</a>{/if}{#if editable}<button class="button secondary" disabled={busy} onclick={()=>run(save)}>Save draft</button>{#if can('submit')}<button class="button primary" disabled={busy} onclick={()=>action('submit')}>Submit for approval<ArrowRight size={16}/></button>{/if}{:else if selected.status==='Pending'&&isApprover()}<button class="button secondary" disabled={busy} onclick={()=>{reviewNote='';modal='changes'}}>Request changes</button><button class="button primary" disabled={busy||!selected.summary.ready} onclick={()=>action('approve')}><Check size={16}/>Approve company</button>{:else if selected.status==='Approved'&&can('amend')}<button class="button primary" disabled={busy} onclick={()=>action('amend')}>Start amendment</button>{/if}</div></div>
{:else if page==='Companies'}
<div class="company-page-heading" use:enter={page}><div><p class="eyebrow">COMPANY MASTER</p><h1>Company register</h1><p>One verified record for every company you work with.</p></div>{#if can('create')}<button class="button primary" onclick={()=>showModal('company')}><Plus size={17}/>Add company</button>{/if}</div>
<div class="company-metrics">{#each [['Total companies',data.companies.length],['Drafts',data.companies.filter((c:Row)=>c.status==='Draft'||c.status==='Changes requested').length],['Awaiting approval',outstanding],['Approved',data.companies.filter((c:Row)=>c.status==='Approved').length]] as metric}<div><span>{metric[0]}</span><strong>{metric[1]}</strong></div>{/each}</div>
<div class="role-explainer"><ShieldCheck size={20}/><p>{can('create')?'Create company drafts, attach KYC and submit for approval.':isSuper()?'Review full KYC, approve companies and configure country-specific fields.':can('approve')?'Review company summaries and approve or request changes.':'View company records within your assigned access.'}</p></div>
<section class="panel"><div class="company-register-toolbar"><div class="filter-tabs">{#each ['All','Draft','Pending','Approved','Changes requested'] as v}<button class:active={status===v} onclick={()=>status=v}>{v==='Pending'?'Awaiting approval':v}</button>{/each}</div><label class="search-box"><Search size={16}/><input aria-label="Search companies" placeholder="Search company or country" bind:value={search}/></label></div>{#if visible.length}<div class="table-wrap"><table><thead><tr><th>Company</th><th>Category</th><th>Type</th><th>Country</th><th>Status</th><th></th></tr></thead><tbody>{#each visible as c}<tr><td><button class="company-name-button" onclick={()=>open(c.id)}>{c.legal_name}<small>{c.city||'Address in progress'}</small></button></td><td>{c.category}</td><td>{c.company_type}</td><td>{c.country}</td><td><span class={'status-chip '+c.status.toLowerCase().replaceAll(' ','-')}>{c.status}</span></td><td><button class="text-button" onclick={()=>open(c.id)}>Open<ArrowRight size={14}/></button></td></tr>{/each}</tbody></table></div>{:else}<div class="company-empty"><span><Building2 size={30}/></span><h2>{data.companies.length?'No matching companies':'Your company register is ready'}</h2><p>{data.companies.length?'Try another search or status.':can('create')?'Add your first company and save its details as a draft.':isFinance()?'No company records are assigned to this account. Contact Admin if you need additional features.':'Companies added by Finance Head will appear here.'}</p>{#if can('create')&&!data.companies.length}<button class="button primary" onclick={()=>showModal('company')}><Plus size={16}/>Add first company</button>{/if}</div>{/if}</section>
{:else if page==='Reminders'}
<div class="company-page-heading" use:enter={page}><div><p class="eyebrow">RENEWALS</p><h1>Expiry reminders</h1><p>Approved company records, due within two calendar months or already expired.</p></div></div><div class:company-warning={!data.email_configured} class:company-notice={data.email_configured}><Mail size={20}/><p>{data.email_configured?'Email delivery is configured. Delivery status appears beside each reminder.':'Dashboard reminders are active. Email delivery needs SMTP settings in the local configuration file.'}</p></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Company</th><th>Document / registration</th><th>Expires</th><th>Validity</th><th>Email status</th><th></th></tr></thead><tbody>{#each data.reminders as r}<tr><td>{r.legal_name}</td><td>{r.label}</td><td>{day(r.expires_on)}</td><td><span class:changes-requested={renewalState(r.expires_on).overdue} class:pending={!renewalState(r.expires_on).overdue} class="status-chip">{renewalState(r.expires_on).label}</span></td><td>{r.email_status}</td><td><button class="text-button" onclick={()=>open(r.company_id)}>Open</button></td></tr>{:else}<tr><td colspan="6" class="section-empty">No renewals due. Enable validity dates on a company field or port registration to track it here.</td></tr>{/each}</tbody></table></div></section>
{:else}
<div class="company-page-heading" use:enter={page}><div><p class="eyebrow">SETUP REGISTERS</p><h1>Fields & ports</h1><p>Country-specific details and the ports available to company records.</p></div></div><section class="panel company-section"><div class="detail-card-heading"><div><h2>Company fields</h2><p class="muted">These are configurable business fields, not an automatic legal-compliance checklist.</p></div>{#if isSuper()}<button class="button primary" onclick={()=>showModal('field')}><Plus size={16}/>Add field</button>{/if}</div><div class="table-wrap"><table><thead><tr><th>Field</th><th>Section</th><th>Country</th><th>Required</th><th>Document</th><th>Validity</th></tr></thead><tbody>{#each data.fields.filter((f:Row)=>f.company_setup_id==null) as f}<tr><td>{f.label}</td><td>{f.section}</td><td>{f.country==='*'?'All':f.country}</td><td>{f.required?'Yes':'Optional'}</td><td>{f.document_required?'Required if used':'Optional'}</td><td>{f.expiry_enabled?'Enabled by default':'Optional'}</td></tr>{/each}</tbody></table></div></section><section class="panel company-section spaced"><div class="detail-card-heading"><h2>Company types</h2>{#if isSuper()}<button class="button secondary" onclick={()=>showModal('type')}><Plus size={16}/>Add company type</button>{/if}</div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Available types</th></tr></thead><tbody>{#each categories as category}<tr><td>{category}</td><td>{(data.types[category]||[]).join(', ')}</td></tr>{/each}</tbody></table></div></section><section class="panel company-section spaced"><div class="detail-card-heading"><h2>Port registry</h2>{#if can('ports')}<button class="button secondary" onclick={()=>showModal('port')}><Plus size={16}/>Register port</button>{/if}</div><div class="table-wrap"><table><thead><tr><th>Port / airport</th><th>Code</th><th>Country</th><th>Mode</th></tr></thead><tbody>{#each data.ports as p}<tr><td>{p.name}</td><td>{p.code||'—'}</td><td>{p.country}</td><td>{p.mode}</td></tr>{:else}<tr><td colspan="4" class="section-empty">No ports registered. Add real ports before linking a company.</td></tr>{/each}</tbody></table></div></section>
{/if}
</main></div></div>
{/if}
{#if modal}
<dialog use:modalDialog class="company-modal" class:address-create-modal={modal==='company'} oncancel={(e)=>{if(busy)e.preventDefault();else modal='';}} aria-modal="true" aria-label={modal==='responsibility'?'Renewal responsibility':modal==='delete'?'Delete company':modal==='company'?'Add company':modal==='field'||modal==='company_field'?'Add field':modal==='changes'?'Request changes':modal==='type'?'Add company type':'Register port'} tabindex="-1"><header><div><p class="eyebrow">COMPANY SETUP</p><h2>{modal==='responsibility'?'Renewal responsibility':modal==='delete'?'Delete company':modal==='company'?'Add a company':modal==='field'||modal==='company_field'?'Add a field':modal==='changes'?'Request changes':modal==='type'?'Add company type':'Register a port'}</h2></div><button class="icon-button" aria-label="Close form" disabled={busy} onclick={()=>modal=''}><X size={20}/></button></header><form onsubmit={modal==='responsibility'?saveResponsibility:modal==='delete'?deleteCompany:modal==='changes'?(e)=>{e.preventDefault();action('request_changes')}:submitModal}>
{#if modal==='responsibility'}<p>The responsible user's dashboard is blocked if a document remains overdue for 30 days. Renewal correction stays available. Super Admin can reassign responsibility.</p><label>Responsible user<select bind:value={responsibleID} required>{#each responsibleUsers as u}<option value={u.id}>{u.name} · {u.designation||u.role}</option>{/each}</select></label>
{:else if modal==='delete'}<p class="company-warning">This removes the company from the register and stops its reminders. Its documents will no longer be accessible. Audit records are retained.</p><p>Type the full company name exactly: <strong>{selected?.legal_name}</strong></p><label>Full company name<input bind:value={deleteName} required autocomplete="off" spellcheck="false"/></label><label>Your current password<input type="password" bind:value={deletePassword} required autocomplete="current-password"/></label>
{:else if modal==='changes'}<label>Changes Finance needs to make<textarea bind:value={reviewNote} required maxlength="500" rows="4" placeholder="Describe missing or incorrect information without including sensitive KYC values."></textarea></label>
{:else if modal==='company'}<div class="company-form-grid"><label class="wide">Legal company name<input bind:value={form.legal_name} required maxlength="150"/></label><label>Category<select bind:value={form.category} onchange={()=>form.company_type=data.types[form.category][0]}>{#each categories as c}<option>{c}</option>{/each}</select></label><label>Type<select bind:value={form.company_type}>{#each data.types[form.category] as t}<option>{t}</option>{/each}</select></label><label>Country code<input bind:value={form.country} required maxlength="2" oninput={()=>{form.country=(form.country||'').replace(/[^a-z]/gi,'').slice(0,2).toUpperCase()}} aria-describedby="company-country-code-help"/><small id="company-country-code-help">Enter any two-letter country code. IN, in, and In are saved as IN.</small></label><BusinessFlowSelect values={businessFlows(form)} disabled={busy} onchange={next=>form.business_flows=next}/><CompanyAddressFields country={form.country} city={form.city} state={form.state} postalCode={form.postal_code} address={form.address} disabled={busy} onchange={patch=>{if(busy)return;if(patch.city!==undefined)form.city=patch.city;if(patch.state!==undefined)form.state=patch.state;if(patch.postalCode!==undefined)form.postal_code=patch.postalCode;if(patch.address!==undefined)form.address=patch.address;}}/></div><p class="muted">Create the draft, then add contacts, KYC, bank accounts, ports and documents.</p>
{:else if modal==='type'}<div class="company-form-grid"><label>Category<select bind:value={form.category}>{#each categories as c}<option>{c}</option>{/each}</select></label><label>Type name<input bind:value={form.label} required maxlength="100"/></label></div>
{:else if modal==='field'||modal==='company_field'}{#if modal==='company_field'}<p class="muted">This field is added only to this company. Fill in its value in Additional, then save your draft.</p>{/if}<fieldset disabled={busy} class="company-form-grid"><label class="wide">Field label<input bind:value={form.label} required maxlength="100"/></label>{#if modal==='field'}<label>Section<select bind:value={form.section}>{#each ['Overview','Contacts','KYC','Bank accounts','Ports','Property','Insurance','Additional','Documents'] as s}<option>{s}</option>{/each}</select></label><label>Country code<input bind:value={form.country} required maxlength="2"/><small>Use * for all countries.</small></label>{/if}<label>Value type<select bind:value={form.input_type}>{#each ['text','textarea','number','date','url','email','tel','select','checkbox'] as t}<option>{t}</option>{/each}</select></label>{#if form.input_type==='select'}<label class="wide">Dropdown choices<textarea rows="4" bind:value={form.options_text} required></textarea><small>One choice per line; 2–50 unique choices.</small></label>{/if}{#if modal==='field'}<fieldset class="wide inline-checks"><legend>Applies to</legend>{#each categories as c}<label><input type="checkbox" value={c} bind:group={form.categories}/>{c}</label>{/each}</fieldset><fieldset class="wide inline-checks"><legend>Business flows (leave all unticked for every flow)</legend>{#each businessModes as mode}<label><input type="checkbox" value={mode} bind:group={form.business_modes}/>{mode}</label>{/each}</fieldset>{/if}<label class="inline-check wide"><input type="checkbox" bind:checked={form.required}/>Require this field before approval</label><label class="inline-check wide"><input type="checkbox" bind:checked={form.document_required}/>Require a supporting document when filled</label><label class="inline-check wide"><input type="checkbox" bind:checked={form.expiry_enabled}/>Enable validity and expiry dates by default</label></fieldset>
{:else}<div class="company-form-grid"><label class="wide">Port / airport name<input bind:value={form.name} required maxlength="100"/></label><label>Port code<input bind:value={form.code}/></label><label>Postal / area code<input bind:value={form.postal_code} maxlength="30"/></label><label class="wide">Port location / address<input bind:value={form.address} maxlength="300"/></label><label>Country code<input bind:value={form.country} minlength="2" maxlength="2" required/></label><label>Transport mode<select bind:value={form.mode}>{#each ['Sea','Air','ICD'] as m}<option>{m}</option>{/each}</select></label></div>{/if}
{#if error}<p class="form-error" role="alert">{error}</p>{/if}<footer><button type="button" class="button secondary" disabled={busy} onclick={()=>modal=''}>Cancel</button><button class="button primary" disabled={busy||(modal==='delete'&&(deleteName!==selected?.legal_name||!deletePassword))}>{busy?'Saving…':modal==='responsibility'?'Renewal responsibility':modal==='delete'?'Delete company':modal==='company'?'Create draft':modal==='changes'?'Send back to Finance':modal==='company_field'?'Add field':'Save'}</button></footer></form></dialog>
{/if}

{#if ready && user && !user.renewal_blocks?.length}
 <Spooly userId={user.id} role={user.role} {portal} {page}/>
{/if}

<style>
 /* Scroll the longer address form between its persistent heading and actions. */
 .company-modal.address-create-modal[open]{display:flex;flex-direction:column;overflow:hidden;padding:0;max-height:90vh}
 .company-modal.address-create-modal>header{flex:none;margin:0!important;top:auto}
 .company-modal.address-create-modal>form{display:flex;flex-direction:column;min-height:0;overflow:hidden}
 .company-modal.address-create-modal>form>.company-form-grid{overflow-y:auto;min-height:0;padding:24px 28px;scroll-padding-block:20px}
 .company-modal.address-create-modal>form>.muted{flex:none;margin:0;padding:0 28px 14px}
 .company-modal.address-create-modal>form>footer{flex:none;margin:0;padding:16px 28px;background:#fff;border-top:1px solid #dce5eb}
 @media(max-width:760px){.company-modal.address-create-modal>form>.company-form-grid{padding:20px 18px}.company-modal.address-create-modal>form>.muted{padding-inline:18px}.company-modal.address-create-modal>form>footer{padding:16px 18px}}
</style>
